@Test
public void testFlowCtrlRuleHandler() {
    try {
        FlowCtrlRuleHandler handler = new FlowCtrlRuleHandler(true);
        handler.updateDefFlowCtrlInfo(1001, 2, 10, mockFlowCtrlInfo());
        TimeZone timeZone = TimeZone.getTimeZone("GMT+8:00");
        Calendar rightNow = Calendar.getInstance(timeZone);
        int hour = rightNow.get(Calendar.HOUR_OF_DAY);
        int minu = rightNow.get(Calendar.MINUTE);
        int curTime = hour * 100 + minu;
        // current data limit test
        FlowCtrlResult result = handler.getCurDataLimit(2000);
        if (curTime >= 800 && curTime <= 1759) {
            assertTrue(result.dataLtInSize == 20 * 1024 * 1024L);
            assertTrue(result.freqLtInMs == 1000L);
        } else if (curTime >= 1800 && curTime < 2200) {
            assertTrue(result.dataLtInSize == 20 * 1024 * 1024L);
            assertTrue(result.freqLtInMs == 5000L);
        } else {
            assertEquals("result should be null", result, null);
        }
        result = handler.getCurDataLimit(1000);
        assertEquals("result should be null", result, null);
        //  request frequency control
        FlowCtrlItem item = handler.getFilterCtrlItem();
        assertEquals(item.getDataLtInSZ(), 0);
        assertEquals(item.getZeroCnt(), 400);
        assertEquals(item.getFreqLtInMs(), 100);
        // check ssd ctrl
        SSDCtrlResult ssdResult = handler.getCurSSDStartDltInSZ();
        if (curTime >= 1200) {
            assertEquals(ssdResult.dataEndDLtInSz, 2048L * 1024L * 1024L);
            assertEquals(ssdResult.dataStartDltInSize, 20480L * 1024L * 1024L);
        } else {
            assertEquals(ssdResult.dataEndDLtInSz, 0L);
            assertEquals(ssdResult.dataStartDltInSize, Long.MAX_VALUE);
        }
        //check values
        assertEquals(handler.getNormFreqInMs(), 100);
        assertEquals(handler.getFlowCtrlId(), 10);
        assertEquals(handler.getMinDataFreqInMs(), 400);
        assertEquals(handler.getMinZeroCnt(), 3);
        assertEquals(handler.getQryPriorityId(), 2);
        assertEquals(handler.getSsdTranslateId(), 1001);
        assertEquals(handler.getFlowCtrlId(), 10);
        System.out.println();
        System.out.println();
    } catch (Exception e) {
        e.printStackTrace();
    }
}

@Test
public void testDataConvert() {
    // broker convert
    BrokerInfo broker = new BrokerInfo(0, "localhost", 1200);
    List<String> strInfoList = new ArrayList<String>();
    strInfoList.add("0:localhost:1200");
    Map<Integer, BrokerInfo> brokerMap = DataConverterUtil.convertBrokerInfo(strInfoList);
    assertEquals("broker should be equal", broker, brokerMap.get(broker.getBrokerId()));
    // partition convert
    Partition partition = new Partition(broker, "tube", 0);
    strInfoList.clear();
    strInfoList.add("0:localhost:1200#tube:0");
    List<Partition> partitionList = DataConverterUtil.convertPartitionInfo(strInfoList);
    assertEquals("partition should be equal", partition, partitionList.get(0));
    // SubscribeInfo convert
    SubscribeInfo subscribeInfo = new SubscribeInfo("001", "group", partition);
    strInfoList.clear();
    strInfoList.add("001@group#0:localhost:1200#tube:0");
    List<SubscribeInfo> subscribeInfoList = DataConverterUtil.convertSubInfo(strInfoList);
    assertEquals("subscribe should be equal", subscribeInfoEqual(subscribeInfo, subscribeInfoList.get(0)), true);
    // topic convert
    TopicInfo topic = new TopicInfo(broker, "tube", 10, 5, true, true);
    strInfoList.clear();
    // topic#brokerId:partitionNum:topicStoreNum
    strInfoList.add("tube#0:10:5");
    List<TopicInfo> topicList = DataConverterUtil.convertTopicInfo(brokerMap, strInfoList);
    assertEquals("topic should be equal", topic, topicList.get(0));
}

@Test
public void testPbEncodeAndDecoder() throws Exception {
    // mock a pb object
    JsonFormat jsonFormat = new JsonFormat();
    ClientMaster.RegisterRequestP2M.Builder builder = ClientMaster.RegisterRequestP2M.newBuilder();
    builder.setClientId("10001");
    builder.setBrokerCheckSum(99);
    builder.setHostName("tube-test");
    ClientMaster.RegisterRequestP2M object = builder.build();
    final String jsonOject = jsonFormat.printToString(object);
    // encode pb
    byte[] data = PbEnDecoder.pbEncode(object);
    // decode bytes
    ClientMaster.RegisterRequestP2M decodeObject = (ClientMaster.RegisterRequestP2M) PbEnDecoder.pbDecode(true, RpcConstants.RPC_MSG_MASTER_PRODUCER_REGISTER, data);
    assertTrue(decodeObject.getClientId().equals(object.getClientId()));
    assertTrue(decodeObject.getBrokerCheckSum() == object.getBrokerCheckSum());
    assertTrue(decodeObject.getHostName().equals(object.getHostName()));
    assertTrue(jsonOject.equals(jsonFormat.printToString(decodeObject)));
}

